"""Roll a run's per-request timings up into one summary line."""

from __future__ import annotations

import statistics
from dataclasses import dataclass


@dataclass(frozen=True)
class RequestTiming:
    request_id: str
    prompt_tokens: int
    completion_tokens: int
    first_token_s: float
    total_s: float

    @property
    def decode_s(self) -> float:
        return self.total_s - self.first_token_s

    @property
    def decode_rate(self) -> float:
        if self.completion_tokens < 2 or self.decode_s <= 0:
            return 0.0
        return (self.completion_tokens - 1) / self.decode_s

    @property
    def prefill_rate(self) -> float:
        return self.prompt_tokens / self.first_token_s if self.first_token_s > 0 else 0.0


def summarize(timings: list[RequestTiming]) -> str:
    if not timings:
        return "no requests"
    decode = [t.decode_rate for t in timings if t.decode_rate > 0]
    prefill = [t.prefill_rate for t in timings if t.prefill_rate > 0]
    ttft = [t.first_token_s for t in timings]
    parts = [f"{len(timings)} requests"]
    if prefill:
        parts.append(f"prefill {statistics.median(prefill):.0f} t/s")
    if decode:
        parts.append(f"decode {statistics.median(decode):.1f} t/s")
    parts.append(f"ttft {statistics.median(ttft) * 1000:.0f} ms")
    return ", ".join(parts)


def load(path: str) -> list[RequestTiming]:
    out = []
    with open(path) as f:
        for line in f:
            rid, p, c, ft, tot = line.rstrip("\n").split("\t")
            out.append(RequestTiming(rid, int(p), int(c), float(ft), float(tot)))
    return out
