// A bounded single-producer, single-consumer ring of byte messages, and a small line protocol on top of it.
//
// The ring holds whole messages. A writer reserves room with reserve(), fills it, and commits with commit(); a reader
// takes the oldest message with next() and returns it with release(). Neither side allocates after construction.

#include <algorithm>
#include <atomic>
#include <cassert>
#include <cstddef>
#include <cstdint>
#include <cstring>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <vector>

namespace ring {

// One message's header, written in front of its bytes. Size is the payload's length; a size of kWrap means "the
// writer could not fit the next message before the end of the buffer: continue from the start".
struct Header {
    uint32_t size;
    uint32_t sequence;
};

constexpr uint32_t kWrap = 0xFFFFFFFFu;
constexpr size_t kAlign = alignof(Header);

inline size_t align_up(size_t n) { return (n + kAlign - 1) & ~(kAlign - 1); }

class MessageRing {
public:
    explicit MessageRing(size_t capacity)
        : buffer_(align_up(capacity)), capacity_(buffer_.size()) {
        assert(capacity_ >= 2 * sizeof(Header));
    }

    MessageRing(const MessageRing&) = delete;
    MessageRing& operator=(const MessageRing&) = delete;

    size_t capacity() const { return capacity_; }

    // Bytes a writer may still reserve, counting the headers it will need.
    size_t free_bytes() const {
        size_t head = head_.load(std::memory_order_acquire);
        size_t tail = tail_.load(std::memory_order_acquire);
        if (tail >= head) return capacity_ - (tail - head) - 1;
        return head - tail - 1;
    }

    // Room for a message of `size` payload bytes, or nothing if the ring is too full. The span is the payload.
    std::optional<std::span<std::byte>> reserve(size_t size) {
        size_t need = sizeof(Header) + align_up(size);
        size_t head = head_.load(std::memory_order_acquire);
        size_t tail = tail_.load(std::memory_order_relaxed);
        if (tail >= head) {
            // Room between tail and the end, or else between the start and head after a wrap marker.
            if (capacity_ - tail >= need + sizeof(Header)) {
                pending_ = tail;
            } else if (head > need) {
                write_header(tail, Header{kWrap, 0});
                pending_ = 0;
            } else {
                return std::nullopt;
            }
        } else {
            if (head - tail <= need) return std::nullopt;
            pending_ = tail;
        }
        pending_size_ = size;
        return std::span<std::byte>(buffer_.data() + pending_ + sizeof(Header), size);
    }

    // Publish the message reserved last. Returns its sequence number.
    uint32_t commit() {
        assert(pending_size_ != kNoPending);
        uint32_t seq = next_sequence_++;
        write_header(pending_, Header{static_cast<uint32_t>(pending_size_), seq});
        size_t end = pending_ + sizeof(Header) + align_up(pending_size_);
        if (end == capacity_) end = 0;
        tail_.store(end, std::memory_order_release);
        pending_size_ = kNoPending;
        return seq;
    }

    struct View {
        std::span<const std::byte> bytes;
        uint32_t sequence;
    };

    // The oldest message not yet released, or nothing if the ring is empty.
    std::optional<View> next() {
        size_t head = head_.load(std::memory_order_relaxed);
        size_t tail = tail_.load(std::memory_order_acquire);
        if (head == tail) return std::nullopt;
        Header h = read_header(head);
        if (h.size == kWrap) {
            head = 0;
            if (head == tail) return std::nullopt;
            h = read_header(head);
        }
        reading_ = head;
        return View{std::span<const std::byte>(buffer_.data() + head + sizeof(Header), h.size), h.sequence};
    }

    // Return the message next() gave, freeing its room.
    void release() {
        assert(reading_ != kNoPending);
        Header h = read_header(reading_);
        size_t end = reading_ + sizeof(Header) + align_up(h.size);
        if (end == capacity_) end = 0;
        head_.store(end, std::memory_order_release);
        reading_ = kNoPending;
    }

private:
    static constexpr size_t kNoPending = static_cast<size_t>(-1);

    void write_header(size_t at, Header h) { std::memcpy(buffer_.data() + at, &h, sizeof h); }
    Header read_header(size_t at) const {
        Header h;
        std::memcpy(&h, buffer_.data() + at, sizeof h);
        return h;
    }

    std::vector<std::byte> buffer_;
    size_t capacity_;
    std::atomic<size_t> head_{0};
    std::atomic<size_t> tail_{0};
    size_t pending_ = kNoPending;
    size_t pending_size_ = kNoPending;
    size_t reading_ = kNoPending;
    uint32_t next_sequence_ = 1;
};

// A text line protocol over the ring: each message is one line without its newline. A writer appends lines; a reader
// pops them as strings. Lines longer than the ring's capacity are refused.
class LineChannel {
public:
    explicit LineChannel(size_t capacity) : ring_(capacity) {}

    bool push_line(std::string_view line) {
        if (line.size() + 2 * sizeof(Header) > ring_.capacity()) return false;
        auto room = ring_.reserve(line.size());
        if (!room) return false;
        std::memcpy(room->data(), line.data(), line.size());
        ring_.commit();
        ++pushed_;
        return true;
    }

    // Append every line of `text`, stopping at the first that does not fit. Returns how many were pushed.
    size_t push_text(std::string_view text) {
        size_t count = 0;
        size_t start = 0;
        while (start <= text.size()) {
            size_t nl = text.find('\n', start);
            std::string_view line = nl == std::string_view::npos ? text.substr(start) : text.substr(start, nl - start);
            if (nl == std::string_view::npos && line.empty()) break;
            if (!push_line(line)) break;
            ++count;
            if (nl == std::string_view::npos) break;
            start = nl + 1;
        }
        return count;
    }

    std::optional<std::string> pop_line() {
        auto v = ring_.next();
        if (!v) return std::nullopt;
        std::string out(reinterpret_cast<const char*>(v->bytes.data()), v->bytes.size());
        ring_.release();
        ++popped_;
        return out;
    }

    size_t pushed() const { return pushed_; }
    size_t popped() const { return popped_; }
    size_t pending() const { return pushed_ - popped_; }

private:
    MessageRing ring_;
    size_t pushed_ = 0;
    size_t popped_ = 0;
};

// A rolling count of lines per second, for a status line.
class RateMeter {
public:
    explicit RateMeter(size_t window) : samples_(window, 0) {}

    void tick(uint64_t now_s, size_t count) {
        if (now_s != last_s_) {
            for (uint64_t s = last_s_ + 1; s <= now_s && s - last_s_ <= samples_.size(); ++s)
                samples_[s % samples_.size()] = 0;
            last_s_ = now_s;
        }
        samples_[now_s % samples_.size()] += count;
    }

    double per_second() const {
        size_t total = 0;
        for (size_t v : samples_) total += v;
        return static_cast<double>(total) / static_cast<double>(samples_.size());
    }

private:
    std::vector<size_t> samples_;
    uint64_t last_s_ = 0;
};

}  // namespace ring

// A small self-check, run when built with -DRING_SELFTEST. It pushes lines until the ring refuses one, pops them all,
// and checks that every line came back in order and that the wrap marker was honoured.
#ifdef RING_SELFTEST
#include <cstdio>

int main() {
    ring::LineChannel ch(256);
    size_t n = ch.push_text("one\ntwo\nthree\nfour\nfive\nsix\nseven\neight\nnine\nten\n");
    std::printf("pushed %zu lines, %zu pending\n", n, ch.pending());
    std::vector<std::string> got;
    while (auto line = ch.pop_line()) got.push_back(*line);
    std::printf("popped %zu lines\n", got.size());
    const char* expect[] = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten"};
    for (size_t i = 0; i < got.size(); ++i) {
        if (got[i] != expect[i]) {
            std::printf("line %zu: got %s, expected %s\n", i, got[i].c_str(), expect[i]);
            return 1;
        }
    }
    // Wrap: fill, drain half, fill again, drain all.
    for (int round = 0; round < 50; ++round) {
        std::string line = "round " + std::to_string(round) + " padding padding padding";
        while (ch.push_line(line)) {}
        for (size_t i = 0; i < ch.pending() / 2; ++i) ch.pop_line();
    }
    while (ch.pop_line()) {}
    if (ch.pending() != 0) {
        std::printf("pending %zu after draining\n", ch.pending());
        return 1;
    }
    std::printf("ok: %zu pushed, %zu popped\n", ch.pushed(), ch.popped());
    return 0;
}
#endif
