263	    std::vector<std::vector<int32_t>> d(n);
264	    std::vector<uint32_t> src(n), live;
265	    for (size_t i = 0; i < n; i++) {
266	      DraftSeed &sd = seeds[i];
267	      if (sd.most == 0 || sd.first.empty()) continue;
268	      std::pair<int32_t, double> pick = sample_p(sd.first, sd.settings, sd.pos, sd.hist);
269	      if (pick.second < draft_min_p) continue;
270	      d[i].push_back(pick.first);
271	      src[i] = sd.src;
272	      if (d[i].size() < sd.most && sd.pos + 2 < info.max_ctx) live.push_back((uint32_t)i);
273	    }
274	    while (!live.empty()) {
275	      std::vector<StepIn> rows;
276	      std::vector<uint32_t> from;
277	      for (uint32_t i : live) {
278	        rows.push_back({seeds[i].slot, seeds[i].pos + (uint32_t)d[i].size() - 2, d[i].back(), kNoToken, kNoToken});
279	        from.push_back(src[i]);
280	      }
281	      auto c = model->mtp_drafts(rows.data(), (uint32_t)rows.size(), from.data());
282	      std::vector<uint32_t> still;
283	      for (size_t k = 0; k < live.size(); k++) {
284	        const uint32_t i = live[k];
285	        DraftSeed &sd = seeds[i];
286	        src[i] = (uint32_t)k;
287	        if (penalised(sd.settings)) sd.hist.push_back(d[i].back());
288	        std::pair<int32_t, double> pick = sample_p(c[k], sd.settings, sd.pos + (uint32_t)d[i].size(), sd.hist);
289	        if (pick.second < draft_min_p) continue;
290	        d[i].push_back(pick.first);
291	        if (d[i].size() < sd.most && sd.pos + d[i].size() + 1 < info.max_ctx) still.push_back(i);
292	      }
293	      live = std::move(still);
294	    }
295	    return d;
296	  }
