298	  // The drafts the i-th of n writing slots may make: the window's rows (STEP_MAX_ROWS) shared out, each slot's row
299	  // first, and at most draft_max, or kSharedDrafts with several slots.
300	  uint32_t draft_share(uint32_t i, uint32_t n) const {
301	    if (n >= STEP_MAX_ROWS) return 0;
302	    const uint32_t spare = STEP_MAX_ROWS - n, most = n > 1 ? std::min(draft_max, kSharedDrafts) : draft_max;
303	    return std::min(most, spare / n + (i < spare % n ? 1u : 0u));
304	  }
