306	  // Whether a slot still has prompt to read. Under mu.
307	  bool reading() const {
308	    for (const Slot &sl : slots)
309	      if (sl.used && !sl.done && sl.fed < sl.prompt.size()) return true;
310	    return false;
311	  }
