313	  // A prompt piece through the prompt path. Runs on the engine thread.
314	  void prompt_piece(uint32_t plan, engine_prompt_piece pc) {
315	    std::vector<int32_t> toks, next;
316	    uint32_t pos0, n;
317	    int32_t p1, p2;
318	    bool windowed, restart;
319	    {
320	      std::lock_guard<std::mutex> lk(mu);
321	      if (pc.slot >= slots.size()) return;
322	      Slot &sl = slots[pc.slot];
323	      if (!sl.used || sl.done || sl.fed >= sl.prompt.size() || info.prompt_chunk == 0) return;
324	      pos0 = sl.fed;
325	      uint32_t left = (uint32_t)sl.prompt.size() - pos0;
326	      n = std::min(left, info.prompt_chunk);
327	      if (pc.tokens) n = std::min(n, pc.tokens);
328	      if (mapped_cells(pc.slot) <= pos0) {
329	        stall(pc.slot, pos0);
330	        return;
331	      }
332	      n = std::min(n, mapped_cells(pc.slot) - pos0);
333	      toks.assign(sl.prompt.begin() + pos0, sl.prompt.begin() + pos0 + n);
334	      p1 = pos0 >= 1 ? sl.tokens[pos0 - 1] : kNoToken;
335	      p2 = pos0 >= 2 ? sl.tokens[pos0 - 2] : kNoToken;
336	      // A decode step takes no cell of an image's block: such a piece goes by the prompt path.
337	      bool image = false;
338	      for (const SlotImage &im : sl.images)
339	        image |= im.first < pos0 + n && im.first + (im.grid_h / 2) * (im.grid_w / 2) > pos0;
340	      windowed = n <= kWindowPrompt && !image;
341	      restart = sl.windows_end != pos0;
342	      // The piece expected next, of the same size, so its n-gram rows are read while this one runs. A short one is
343	      // read as windows, which gather their own rows.
344	      const uint32_t nn = std::min(left - n, pc.tokens ? std::min(pc.tokens, info.prompt_chunk) : info.prompt_chunk);
345	      if (!windowed && nn > kWindowPrompt)
346	        next.assign(sl.prompt.begin() + pos0 + n, sl.prompt.begin() + pos0 + n + nn);
347	    }
348	    if (windowed) {
349	      prompt_windows(plan, pc.slot, pos0, toks, p1, p2, restart);
350	      return;
351	    }
352	    uint64_t t0 = now_ns();
353	    auto cand = model->prompt(pc.slot, pos0, toks.data(), n, p1, p2, next.empty() ? nullptr : next.data(),
354	                              (uint32_t)next.size());
355	    std::lock_guard<std::mutex> lk(mu);
356	    record({ENGINE_TIMING_PROMPT, plan, n, 0, t0, now_ns()});
357	    Slot &sl = slots[pc.slot];
358	    if (!sl.used) return;  // released while it ran
359	    sl.tokens.insert(sl.tokens.end(), toks.begin(), toks.end());
360	    if (model->drafting()) sl.lookup.index(sl.tokens);  // a piece at a time, not all at the first round
361	    sl.fed = pos0 + n;
362	    emit({ENGINE_EVENT_PROMPT, pc.slot, kNoToken, sl.fed});
363	    if (sl.fed != sl.prompt.size()) return;
364	    prompt_ended = true;
365	    produce(pc.slot, cand);
366	    if (!model->drafting() || sl.done) return;
367	    // The draft layer reads the prompt's last rows (its cells start there), and drafts.
368	    uint32_t k = std::min<uint32_t>(n, STEP_MAX_ROWS), fed = sl.fed;
369	    std::vector<StepIn> mr;
370	    for (uint32_t j = 0; j < k; j++) {
371	      uint32_t pos = fed - k + j;
372	      mr.push_back({pc.slot, pos, pos + 1 < fed ? sl.tokens[pos + 1] : sl.next, kNoToken, kNoToken});
373	    }
374	    model->mtp_start(pc.slot, fed - k);
375	    auto dc = model->mtp_catchup_prompt(mr.data(), k, n);
376	    sl.drafts = make_drafts(pc.slot, sl.settings, fed + 1, dc[k - 1], k - 1, draft_history(sl));  // under mu: admit and release wait for it
377	  }
378	
379	  // A short prompt piece as decode windows of up to STEP_MAX_ROWS forced rows, each committed whole. The draft layer
380	  // reads every row, from pos0 on when restart (its cells before were never computed). Then as prompt_piece. Runs on
381	  // the engine thread.
382	  void prompt_windows(uint32_t plan, uint32_t s, uint32_t pos0, const std::vector<int32_t> &toks, int32_t p1,
383	                      int32_t p2, bool restart) {
384	    const uint32_t n = (uint32_t)toks.size();
385	    const bool mtp = model->drafting();
386	    int32_t after;  // the prompt's token after the piece, or kNoToken when the piece ends the prompt
387	    {
388	      std::lock_guard<std::mutex> lk(mu);
389	      const Slot &sl = slots[s];
390	      after = pos0 + n < sl.prompt.size() ? sl.prompt[pos0 + n] : kNoToken;
391	    }
392	    uint64_t t0 = now_ns();
393	    if (mtp && restart) model->mtp_start(s, pos0);
394	    std::vector<Candidate> cand;
395	    std::vector<StepIn> mr;  // the last window's rows for the draft layer, each with the token after it
396	    for (uint32_t i = 0; i < n; i += STEP_MAX_ROWS) {
397	      const uint32_t w = std::min<uint32_t>(STEP_MAX_ROWS, n - i);
398	      std::vector<StepIn> rows;
399	      for (uint32_t k = i; k < i + w; k++) {
400	        const int32_t a = k >= 1 ? toks[k - 1] : p1, b = k >= 2 ? toks[k - 2] : k == 1 ? p1 : p2;
401	        rows.push_back({s, pos0 + k, toks[k], a, b});
402	      }
403	      auto out = model->step(rows.data(), w, true, true);
404	      model->commit(s, pos0 + i, w);
405	      cand = out[w - 1];
406	      mr.clear();
407	      for (uint32_t k = i; k < i + w; k++)
408	        mr.push_back({s, pos0 + k, k + 1 < n ? toks[k + 1] : after, kNoToken, kNoToken});
409	      // The last row's next token is sampled below when the piece ends the prompt.
410	      if (mtp && mr.back().token != kNoToken) model->mtp_catchup(mr.data(), w);
411	    }
412	    std::lock_guard<std::mutex> lk(mu);
413	    record({ENGINE_TIMING_PROMPT, plan, n, 0, t0, now_ns()});
414	    Slot &sl = slots[s];
415	    if (!sl.used) return;  // released while it ran
416	    sl.tokens.insert(sl.tokens.end(), toks.begin(), toks.end());
417	    if (mtp) sl.lookup.index(sl.tokens);  // as prompt_piece
418	    sl.fed = pos0 + n;
419	    sl.windows_end = sl.fed;
420	    emit({ENGINE_EVENT_PROMPT, s, kNoToken, sl.fed});
421	    if (sl.fed != sl.prompt.size()) return;
422	    prompt_ended = true;
423	    produce(s, cand);
424	    if (!mtp || sl.done) return;
425	    mr.back().token = sl.next;
426	    auto dc = model->mtp_catchup(mr.data(), (uint32_t)mr.size());
427	    sl.drafts = make_drafts(s, sl.settings, sl.fed + 1, dc.back(), (uint32_t)mr.size() - 1, draft_history(sl));  // under mu, as above
428	  }
