430	  // One decode step for the plan's slots, batched. Runs on the engine thread.
431	  void decode(uint32_t plan, const engine_step_plan &p) {
432	    std::vector<StepIn> rows;
433	    std::vector<uint32_t> who;
434	    {
435	      std::lock_guard<std::mutex> lk(mu);
436	      for (uint32_t i = 0; i < p.nslots && i < ENGINE_MAX_STEP_SLOTS; i++) {
437	        uint32_t s = p.slots[i];
438	        if (s >= slots.size() || std::find(who.begin(), who.end(), s) != who.end()) continue;
439	        Slot &sl = slots[s];
440	        if (!sl.used || sl.done) continue;
441	        if (sl.fed >= info.max_ctx) {
442	          sl.done = true;
443	          emit({ENGINE_EVENT_DONE, s, kNoToken, ENGINE_DONE_CONTEXT});
444	          continue;
445	        }
446	        if (sl.fed >= mapped_cells(s)) {
447	          stall(s, sl.fed);
448	          continue;
449	        }
450	        int32_t tok = sl.fed < sl.prompt.size() ? sl.prompt[sl.fed] : sl.next;
451	        uint32_t pos = sl.fed;
452	        rows.push_back({s, pos, tok, pos >= 1 ? sl.tokens[pos - 1] : kNoToken, pos >= 2 ? sl.tokens[pos - 2] : kNoToken});
453	        who.push_back(s);
454	      }
455	    }
456	    writers = (uint32_t)rows.size();
457	    if (rows.empty()) return;
458	    {
459	      std::unique_lock<std::mutex> lk(mu);
460	      Slot &sl = slots[who[0]];
461	      if (rows.size() == 1 && model->drafting() && sl.fed >= sl.prompt.size()) {
462	        // A lone writing slot's own tokens may give better drafts than the draft layer
463	        // (docs/adr/0041-drafts-from-the-slots-own-tokens.md).
464	        std::vector<int32_t> look = sl.lookup.drafts(sl.tokens, rows[0].token, STEP_MAX_ROWS - 1, media);
465	        const uint32_t take = engine::choose_drafts(sl.odds, (uint32_t)sl.drafts.size(), draft_max,
466	                                                    (uint32_t)look.size(), STEP_MAX_ROWS, window_times);
467	        sl.lookup_round = take > 0;
468	        if (take) look.resize(take), sl.drafts = std::move(look);
469	      }
470	      if (rows.size() == 1 && model->drafting() && sl.fed >= sl.prompt.size() && !sl.drafts.empty()) {
471	        std::vector<int32_t> d = sl.drafts;
472	        lk.unlock();
473	        round(plan, rows[0], d);
474	        return;
475	      }
476	      // Several slots, all writing, some with drafts: their windows in one pass. Not while a prompt is read, nor for a
477	      // slot's second token, which already waits for the prompt steps after its first: a round there would lengthen
478	      // the step that ends the wait (docs/MEASUREMENTS.md#2026-10-19-draft-rounds-several-writers).
479	      bool writing = model->drafting() && rows.size() > 1 && !reading(), any = false;
480	      std::vector<std::vector<int32_t>> ds;
481	      for (uint32_t s : who) {
482	        writing = writing && slots[s].fed >= slots[s].prompt.size() && slots[s].generated > 1;
483	        any = any || !slots[s].drafts.empty();
484	        ds.push_back(slots[s].drafts);
485	      }
486	      if (writing && any) {
487	        lk.unlock();
488	        rounds(plan, rows, ds);
489	        return;
490	      }
491	    }
492	    uint64_t t0 = now_ns();
493	    auto out = model->step(rows.data(), (uint32_t)rows.size());
494	    std::vector<StepIn> mr;  // the draft layer's catch-up: each row with the token after it
495	    {
496	      std::lock_guard<std::mutex> lk(mu);
497	      const uint64_t t1 = now_ns();
498	      record({ENGINE_TIMING_DECODE, plan, (uint32_t)rows.size(), model->last_stats().misses, t0, t1});
499	      if (rows.size() == 1) window_times.add(1, (t1 - t0) * 1e-6);
500	      for (size_t i = 0; i < rows.size(); i++) {
501	        uint32_t s = who[i];
502	        Slot &sl = slots[s];
503	        if (!sl.used) continue;
504	        sl.tokens.push_back(rows[i].token);
505	        sl.fed = rows[i].pos + 1;
506	        if (sl.fed < sl.prompt.size()) {
507	          if (sl.fed % 512 == 0) emit({ENGINE_EVENT_PROMPT, s, kNoToken, sl.fed});
508	          mr.push_back({s, rows[i].pos, sl.prompt[sl.fed], kNoToken, kNoToken});
509	          continue;
510	        }
511	        if (sl.fed == sl.prompt.size()) emit({ENGINE_EVENT_PROMPT, s, kNoToken, sl.fed});
512	        produce(s, out[i]);
513	        sl.drafts.clear();
514	        mr.push_back({s, rows[i].pos, sl.next, kNoToken, kNoToken});
515	      }
516	    }
517	    // The draft layer reads every computed row, so its cells stay whole; writing slots get drafts.
518	    if (!model->drafting() || mr.empty()) return;
519	    auto dc = model->mtp_catchup(mr.data(), (uint32_t)mr.size());
520	    if (mr.size() != 1) {
521	      std::vector<DraftSeed> seeds;
522	      {
523	        std::lock_guard<std::mutex> lk(mu);
524	        if (reading()) return;
525	        for (uint32_t i = 0; i < mr.size(); i++) {
526	          const Slot &sl = slots[mr[i].slot];
527	          if (sl.used && !sl.done)
528	            seeds.push_back({mr[i].slot, sl.settings, sl.fed + 1, dc[i], i, draft_share(i, (uint32_t)mr.size()),
529	                             draft_history(sl)});
530	        }
531	      }
532	      auto d = make_drafts_many(seeds);
533	      std::lock_guard<std::mutex> lk(mu);
534	      for (size_t i = 0; i < seeds.size(); i++) {
535	        Slot &sl = slots[seeds[i].slot];
536	        if (sl.used && !sl.done) sl.drafts = d[i];
537	      }
538	      return;
539	    }
540	    std::unique_lock<std::mutex> lk(mu);
541	    Slot &sl = slots[mr[0].slot];
542	    if (!sl.used || sl.done || sl.fed < sl.prompt.size()) return;
543	    const uint32_t s = mr[0].slot, pos = sl.fed + 1;
544	    const engine_settings st = sl.settings;
545	    std::vector<int32_t> h = draft_history(sl);
546	    lk.unlock();
547	    auto d = make_drafts(s, st, pos, dc[0], 0, std::move(h));
548	    lk.lock();
549	    if (slots[s].used && !slots[s].done) slots[s].drafts = d;
550	  }
