552	  // A draft round for one slot (docs/spec/STRATA_DECODE.md, sections 1-3): row 0 (the token sampled last) and the
553	  // drafts verified in one window; the drafts accepted while each equals the token sampled after the row before it,
554	  // and the next token after them; the accepted rows committed; the draft layer catches up and drafts again.
555	  void round(uint32_t plan, StepIn row0, const std::vector<int32_t> &drafts) {
556	    const uint32_t s = row0.slot, p = row0.pos;
557	    uint32_t k = (uint32_t)std::min<size_t>(drafts.size(), info.max_ctx - 1 - p);
558	    k = std::min<uint32_t>(k, STEP_MAX_ROWS - 1);
559	    {
560	      std::lock_guard<std::mutex> lk(mu);
561	      k = std::min(k, mapped_cells(s) - 1 - p);  // the window's rows only where the slot has pages (decode checked p)
562	    }
563	    std::vector<StepIn> rows{row0};
564	    for (uint32_t j = 0; j < k; j++) {
565	      const StepIn &b = rows.back();
566	      rows.push_back({s, p + 1 + j, drafts[j], b.token, b.p1});
567	    }
568	    uint64_t t0 = now_ns();
569	    auto out = model->step(rows.data(), (uint32_t)rows.size(), true);
570	    std::vector<int32_t> picks;
571	    engine_settings settings;
572	    std::vector<int32_t> hist;  // the tokens before the row being sampled, for the penalties
573	    {
574	      std::lock_guard<std::mutex> lk(mu);
575	      settings = slots[s].settings;
576	      hist = penalty_window(slots[s].tokens, settings);
577	    }
578	    const bool pen = penalised(settings);
579	    uint32_t a = 0;
580	    for (; a <= k; a++) {
581	      if (pen) hist.push_back(rows[a].token);
582	      picks.push_back(sample_p(out[a], settings, p + a + 1, hist).first);
583	      if (a == k || drafts[a] != picks[a]) break;
584	    }
585	    model->commit(s, p, a + 1);
586	    bool done;
587	    {
588	      std::lock_guard<std::mutex> lk(mu);
589	      const uint64_t t1 = now_ns();
590	      record({ENGINE_TIMING_ROUND, plan, (uint32_t)rows.size(), model->last_stats().misses, t0, t1});
591	      window_times.add((uint32_t)rows.size(), (t1 - t0) * 1e-6);
592	      Slot &sl = slots[s];
593	      if (!sl.used) return;
594	      if (sl.lookup_round)
595	        sl.odds.lookup_round(a, k);
596	      else if (k)
597	        sl.odds.layer_round(a);
598	      sl.lookup_round = false;
599	      for (uint32_t j = 0; j <= a; j++) sl.tokens.push_back(rows[j].token);
600	      sl.fed = p + a + 1;
601	      done = false;
602	      for (uint32_t j = 0; j <= a && !done; j++) done = emit_token(s, picks[j], p + j + 1);
603	      sl.drafts.clear();
604	    }
605	    if (done) return;
606	    std::vector<StepIn> mr;
607	    for (uint32_t j = 0; j <= a; j++) mr.push_back({s, p + j, picks[j], kNoToken, kNoToken});
608	    auto dc = model->mtp_catchup(mr.data(), (uint32_t)mr.size());
609	    if (pen) hist.push_back(picks[a]);
610	    auto d = make_drafts(s, settings, p + a + 2, dc[a], a, std::move(hist));
611	    std::lock_guard<std::mutex> lk(mu);
612	    if (slots[s].used && !slots[s].done) slots[s].drafts = d;
613	  }
614	
615	  // A draft round for several slots in one window (round, slot by slot): each slot's run of rows, its token sampled
616	  // last and its drafts, as many as the window's rows allow. Each run is accepted and committed as round's one, then
617	  // the draft layer catches up on every row of the window (a run's rows past its accepted ones only fill cells that
618	  // are written again before any row reads them) and drafts again for every slot. Runs on the engine thread.
619	  void rounds(uint32_t plan, const std::vector<StepIn> &row0, const std::vector<std::vector<int32_t>> &drafts) {
620	    const uint32_t ns = (uint32_t)row0.size();
621	    std::vector<uint32_t> start(ns), k(ns);
622	    std::vector<StepIn> rows;
623	    {
624	      std::lock_guard<std::mutex> lk(mu);
625	      for (uint32_t i = 0; i < ns; i++) {
626	        const uint32_t s = row0[i].slot, p = row0[i].pos;
627	        uint32_t ki = (uint32_t)std::min<size_t>(drafts[i].size(), info.max_ctx - 1 - p);
628	        ki = std::min(ki, mapped_cells(s) - 1 - p);
629	        ki = std::min<uint32_t>(ki, STEP_MAX_ROWS - (uint32_t)rows.size() - (ns - i));
630	        start[i] = (uint32_t)rows.size();
631	        k[i] = ki;
632	        rows.push_back(row0[i]);
633	        for (uint32_t j = 0; j < ki; j++) {
634	          const StepIn &b = rows.back();
635	          rows.push_back({s, p + 1 + j, drafts[i][j], b.token, b.p1});
636	        }
637	      }
638	    }
639	    const uint32_t n = (uint32_t)rows.size();
640	    uint64_t t0 = now_ns();
641	    auto out = model->step(rows.data(), n, true);
642	    std::vector<engine_settings> settings(ns);
643	    std::vector<std::vector<int32_t>> hist(ns);  // each slot's tokens before the row being sampled, for the penalties
644	    {
645	      std::lock_guard<std::mutex> lk(mu);
646	      for (uint32_t i = 0; i < ns; i++) {
647	        settings[i] = slots[row0[i].slot].settings;
648	        hist[i] = penalty_window(slots[row0[i].slot].tokens, settings[i]);
649	      }
650	    }
651	    std::vector<std::vector<int32_t>> picks(ns);
652	    std::vector<uint32_t> acc(ns);
653	    std::vector<CommitRun> runs;
654	    for (uint32_t i = 0; i < ns; i++) {
655	      const uint32_t p = row0[i].pos;
656	      const bool pen = penalised(settings[i]);
657	      uint32_t a = 0;
658	      for (; a <= k[i]; a++) {
659	        if (pen) hist[i].push_back(rows[start[i] + a].token);
660	        picks[i].push_back(sample_p(out[start[i] + a], settings[i], p + a + 1, hist[i]).first);
661	        if (a == k[i] || drafts[i][a] != picks[i][a]) break;
662	      }
663	      acc[i] = a;
664	      runs.push_back({a + 1, p, row0[i].slot, start[i]});
665	    }
666	    model->commit_runs(runs.data(), ns);
667	    std::vector<bool> live(ns, false);
668	    {
669	      std::lock_guard<std::mutex> lk(mu);
670	      record({ENGINE_TIMING_ROUND, plan, n, model->last_stats().misses, t0, now_ns()});
671	      for (uint32_t i = 0; i < ns; i++) {
672	        const uint32_t s = row0[i].slot, p = row0[i].pos, a = acc[i];
673	        Slot &sl = slots[s];
674	        if (!sl.used) continue;
675	        for (uint32_t j = 0; j <= a; j++) sl.tokens.push_back(rows[start[i] + j].token);
676	        sl.fed = p + a + 1;
677	        bool done = false;
678	        for (uint32_t j = 0; j <= a && !done; j++) done = emit_token(s, picks[i][j], p + j + 1);
679	        sl.drafts.clear();
680	        live[i] = !done;
681	      }
682	    }
683	    std::vector<StepIn> mr;
684	    for (uint32_t i = 0; i < ns; i++)
685	      for (uint32_t j = 0; j <= k[i]; j++) {
686	        const StepIn &r = rows[start[i] + j];
687	        mr.push_back({r.slot, r.pos, j < acc[i] ? rows[start[i] + j + 1].token : picks[i][acc[i]], kNoToken, kNoToken});
688	      }
689	    auto dc = model->mtp_catchup(mr.data(), n);
690	    {
691	      std::lock_guard<std::mutex> lk(mu);
692	      if (reading()) return;  // a request admitted while the round ran
693	    }
694	    std::vector<DraftSeed> seeds;
695	    for (uint32_t i = 0; i < ns; i++)
696	      if (live[i]) {
697	        const uint32_t r = start[i] + acc[i];
698	        if (penalised(settings[i])) hist[i].push_back(picks[i][acc[i]]);
699	        seeds.push_back({row0[i].slot, settings[i], row0[i].pos + acc[i] + 2, dc[r], r, draft_share(i, ns),
700	                         std::move(hist[i])});

 701	      }
 702	    auto d = make_drafts_many(seeds);
 703	    std::lock_guard<std::mutex> lk(mu);
 704	    for (size_t i = 0; i < seeds.size(); i++) {
 705	      Slot &sl = slots[seeds[i].slot];
 706	      if (sl.used && !sl.done) sl.drafts = d[i];
 707	    }
 708	  }
 709	
 710	  void run() {
 711	    for (;;) {
 712	      engine_step_plan plan;
 713	      std::vector<engine_page_change> pages;
 714	      uint32_t seq;
 715	      {
 716	        std::unique_lock<std::mutex> lk(mu);
 717	        cv.wait(lk, [&] { return stop || !plans.empty(); });
 718	        if (stop) return;
 719	        plan = plans.front().plan;
 720	        pages = std::move(plans.front().pages);
 721	        plans.pop_front();
 722	        seq = ++plans_taken;
 723	        running = true;
 724	        prompt_ended = false;
 725	        writers = 0;
 726	      }
 727	      try {
 728	        apply_pages(pages);
 729	        for (uint32_t i = 0; i < plan.npieces && i < ENGINE_MAX_PROMPT_PIECES; i++) {
 730	          prompt_piece(seq, plan.pieces[i]);
 731	          if (swaps) model->note_prompt_routing();
 732	        }
 733	        decode(seq, plan);
 734	        // A swap round after a plan that ended a prompt, and after every 8th plan while at most one slot writes, every
 735	        // 16th while several do (docs/MEASUREMENTS.md#2026-10-20-swap-cadence-and-fill). Never while a slot reads its prompt
 736	        // (docs/MEASUREMENTS.md#2026-10-16-drafting-and-swaps). While several slots write, the round's swaps are
 737	        // shared out: the cache follows several requests' routing at once.
 738	        const uint32_t every = writers > 1 ? 16 : 8;
 739	        if (swaps && (prompt_ended || seq % every == 0) && !prompt_reading())
 740	          model->swap_round(64 / std::max<uint32_t>(1, writers));
 741	        std::lock_guard<std::mutex> lk(mu);
 742	        emit({ENGINE_EVENT_STEP, 0, kNoToken, ++plans_done});
 743	      } catch (const std::exception &ex) {
 744	        std::lock_guard<std::mutex> lk(mu);
 745	        error = ex.what();
 746	        plans_done++;
 747	        emit({ENGINE_EVENT_ERROR, 0, kNoToken, ENGINE_ERROR});
 748	      }
 749	      std::lock_guard<std::mutex> lk(mu);
 750	      running = false;
 751	      idle_cv.notify_all();
 752	    }
 753	  }
 754	
 755	  // Whether a slot is still reading its prompt.
 756	  bool prompt_reading() {
 757	    std::lock_guard<std::mutex> lk(mu);
 758	    for (const Slot &sl : slots)
 759	      if (sl.used && !sl.done && sl.fed < sl.prompt.size()) return true;
 760	    return false;
 761	  }
 762	
 763	  // Waits until every queued plan has run. Under the lock lk.
 764	  void drain(std::unique_lock<std::mutex> &lk) {
 765	    idle_cv.wait(lk, [&] { return plans.empty() && !running; });
 766	  }
 767	
 768	  // Whether the engine sleeps, with the error saying so. Under mu.
 769	  bool sleeping() {
 770	    if (asleep) error = "the engine is asleep";
 771	    return asleep;
 772	  }
 773	
 774	  // The checkpoints' pinned memory, each a slot's fixed state (docs/DESIGN.md, section 6): at open and at a wake, never
 775	  // on the token path. Under mu.
 776	  void pin_checkpoints() {
 777	    for (auto &ck : checkpoints) {
 778	      if (!ck.data) ck.data = static_cast<uint8_t *>(model->alloc_pinned(checkpoint_bytes));
 779	      ck.bytes = checkpoint_bytes;
 780	    }
 781	  }
 782	  void unpin_checkpoints() {
 783	    for (auto &ck : checkpoints) {
 784	      if (ck.data) model->free_pinned(ck.data);
 785	      ck = Checkpoint{};
 786	    }
 787	  }
 788	};
