 851	engine_status engine_admit(engine_ctx *e, uint32_t slot, const engine_settings *settings, const int32_t *prompt,
 852	                           uint32_t n_prompt) {
 853	  if (!e || !settings || (!prompt && n_prompt) || n_prompt == 0) return ENGINE_BAD_ARGUMENT;
 854	  std::lock_guard<std::mutex> lk(e->mu);
 855	  if (slot >= e->slots.size()) return ENGINE_BAD_ARGUMENT;
 856	  if (n_prompt > e->info.max_ctx) return ENGINE_BAD_ARGUMENT;
 857	  if (!(settings->min_p >= 0.0f && settings->min_p <= 1.0f)) return ENGINE_BAD_ARGUMENT;
 858	  if (penalised(*settings) && !(settings->penalty_repeat > 0.0f)) return ENGINE_BAD_ARGUMENT;
 859	  if (e->sleeping()) return ENGINE_ERROR;
 860	  Slot &sl = e->slots[slot];
 861	  if (sl.used) return ENGINE_BUSY;
 862	  try {
 863	    // Nothing runs on the slot: the engine thread skips unused slots, and the slot was free.
 864	    e->model->reset_slot(slot);
 865	  } catch (const std::exception &ex) {
 866	    e->error = ex.what();
 867	    return ENGINE_ERROR;
 868	  }
 869	  sl = Slot{};
 870	  sl.used = true;
 871	  sl.settings = *settings;
 872	  e->mapped[slot] = e->queued_mapped[slot] = 0;
 873	  sl.prompt.assign(prompt, prompt + n_prompt);
 874	  return ENGINE_OK;
 875	}
