 877	engine_status engine_admit_images(engine_ctx *e, uint32_t slot, const engine_image *images, uint32_t n) {
 878	  if (!e || (!images && n)) return ENGINE_BAD_ARGUMENT;
 879	  std::lock_guard<std::mutex> lk(e->mu);
 880	  if (slot >= e->slots.size()) return ENGINE_BAD_ARGUMENT;
 881	  if (e->sleeping()) return ENGINE_ERROR;
 882	  Slot &sl = e->slots[slot];
 883	  if (!sl.used || sl.fed != 0) return ENGINE_BAD_ARGUMENT;
 884	  if (n && !e->info.image_tokens_max) {
 885	    e->error = "no image encoder: open with vision_path";
 886	    return ENGINE_BAD_ARGUMENT;
 887	  }
 888	  std::vector<SlotImage> ims;
 889	  std::vector<engine::qwen4exp::Image> mi;
 890	  uint32_t end = 0;
 891	  for (uint32_t i = 0; i < n; i++) {
 892	    const engine_image &im = images[i];
 893	    const uint64_t tokens = (uint64_t)(im.grid_h / 2) * (im.grid_w / 2);
 894	    if (!im.pixels || !tokens || im.grid_h % 2 || im.grid_w % 2 || (im.frames != 1 && im.frames != 2) ||
 895	        tokens > e->info.image_tokens_max || im.first < end || im.first + tokens > sl.prompt.size()) {
 896	      e->error = "image " + std::to_string(i) + ": out of range, out of order, too large or not 1 or 2 frames";
 897	      return ENGINE_BAD_ARGUMENT;
 898	    }
 899	    const int32_t pad = im.frames == 1 ? kImageToken : kVideoToken;
 900	    for (uint64_t t = im.first; t < im.first + tokens; t++)
 901	      if (sl.prompt[t] != pad) {
 902	        e->error = "image " + std::to_string(i) + ": the prompt's block is not " +
 903	                   (im.frames == 1 ? "image" : "video") + " tokens";
 904	        return ENGINE_BAD_ARGUMENT;
 905	      }
 906	    end = (uint32_t)(im.first + tokens);
 907	    auto px = std::make_shared<const std::vector<uint8_t>>(im.pixels, im.pixels + tokens * 4 * 768 * im.frames);
 908	    ims.push_back({im.first, im.grid_h, im.grid_w, im.frames, px});
 909	    mi.push_back({im.first, im.frames, im.grid_h, im.grid_w, px->data()});
 910	  }
 911	  try {
 912	    // Nothing runs on the slot: it has read nothing yet, and the engine thread reads a slot's images only for it.
 913	    e->model->set_images(slot, mi.data(), n);
 914	  } catch (const std::exception &ex) {
 915	    e->error = ex.what();
 916	    return ENGINE_BAD_ARGUMENT;
 917	  }
 918	  sl.images = std::move(ims);
 919	  return ENGINE_OK;
 920	}
