 930	engine_status engine_submit(engine_ctx *e, const engine_step_plan *plan) {
 931	  if (!e || !plan || plan->nslots > ENGINE_MAX_STEP_SLOTS || plan->npieces > ENGINE_MAX_PROMPT_PIECES ||
 932	      (plan->npages && !plan->pages))
 933	    return ENGINE_BAD_ARGUMENT;
 934	  std::lock_guard<std::mutex> lk(e->mu);
 935	  if (e->sleeping()) return ENGINE_ERROR;
 936	  if (e->plans.size() >= 64) return ENGINE_BUSY;
 937	  // The page changes against the tables as the plans queued before leave them, all or none.
 938	  const uint32_t C = e->info.cards, kvp = e->info.kv_pages, npp = e->info.pages_per_slot;
 939	  std::vector<uint32_t> after = e->queued_mapped;
 940	  for (uint32_t i = 0; i < plan->npages; i++) {
 941	    const engine_page_change &c = plan->pages[i];
 942	    std::string bad;
 943	    if (c.slot >= e->slots.size() || c.logical > after[c.slot] || c.logical >= npp)
 944	      bad = "logical page out of order or past the slot's table";
 945	    else if (c.page != ENGINE_NO_PAGE && (c.page >= kvp || c.page % C != c.logical % C))
 946	      bad = "page out of the pool, or on the wrong card for its logical page";
 947	    else if (c.page != ENGINE_NO_PAGE && c.cells &&
 948	             (c.cells >= KV_PAGE_CELLS || c.source >= kvp || c.source % C != c.page % C))
 949	      bad = "copy from a page out of the pool or on the wrong card, or of a whole page";
 950	    if (!bad.empty()) {
 951	      e->error = "page change " + std::to_string(i) + " (slot " + std::to_string(c.slot) + ", logical " +
 952	                 std::to_string(c.logical) + "): " + bad;
 953	      return ENGINE_BAD_ARGUMENT;
 954	    }
 955	    if (c.page == ENGINE_NO_PAGE)
 956	      after[c.slot] = c.logical;
 957	    else if (c.logical == after[c.slot])
 958	      after[c.slot]++;
 959	  }
 960	  e->queued_mapped = std::move(after);
 961	  e->plans.push_back({*plan, std::vector<engine_page_change>(plan->pages, plan->pages + plan->npages)});
 962	  e->plans.back().plan.pages = nullptr;
 963	  e->cv.notify_all();
 964	  return ENGINE_OK;
 965	}
