1007	engine_status engine_restore(engine_ctx *e, uint32_t slot, uint32_t id) {
1008	  if (!e) return ENGINE_BAD_ARGUMENT;
1009	  std::unique_lock<std::mutex> lk(e->mu);
1010	  if (slot >= e->slots.size() || id >= e->checkpoints.size()) return ENGINE_BAD_ARGUMENT;
1011	  if (e->sleeping()) return ENGINE_ERROR;
1012	  e->drain(lk);
1013	  Slot &sl = e->slots[slot];
1014	  Checkpoint &ck = e->checkpoints[id];
1015	  if (!sl.used || !ck.full || sl.fed != 0) return ENGINE_BAD_ARGUMENT;
1016	  // The checkpoint's tokens must start the slot's prompt, and leave at least one to read (its last row's logits are
1017	  // not kept).
1018	  if (ck.tokens.size() >= sl.prompt.size() || !std::equal(ck.tokens.begin(), ck.tokens.end(), sl.prompt.begin()))
1019	    return ENGINE_BAD_ARGUMENT;
1020	  if (images_before(sl.images, (uint32_t)ck.tokens.size()) != ck.images) return ENGINE_BAD_ARGUMENT;
1021	  try {
1022	    e->model->load_slot(slot, ck.data);
1023	  } catch (const std::exception &ex) {
1024	    e->error = ex.what();
1025	    return ENGINE_ERROR;
1026	  }
1027	  sl.tokens = ck.tokens;
1028	  sl.fed = (uint32_t)ck.tokens.size();
1029	  return ENGINE_OK;
1030	}
