1076	engine_status engine_wake(engine_ctx *e, engine_info *info) {
1077	  if (!e) return ENGINE_BAD_ARGUMENT;
1078	  std::lock_guard<std::mutex> lk(e->mu);
1079	  if (e->asleep) {
1080	    try {
1081	      e->pin_checkpoints();
1082	      e->model->wake();
1083	    } catch (const std::exception &ex) {
1084	      e->error = ex.what();
1085	      e->unpin_checkpoints();
1086	      return ENGINE_ERROR;
1087	    }
1088	    e->asleep = false;
1089	    // The model woke with its own table (each slot its own run of pages); Python maps every slot afresh.
1090	    for (auto &row : e->table) std::fill(row.begin(), row.end(), 0u);
1091	    std::fill(e->mapped.begin(), e->mapped.end(), 0u);
1092	    std::fill(e->queued_mapped.begin(), e->queued_mapped.end(), 0u);
1093	    const auto &li = e->model->info();
1094	    e->info.experts_per_layer = li.experts_per_layer;
1095	    e->info.device_bytes[0] = li.device_bytes[0];
1096	    e->info.device_bytes[1] = li.device_bytes[1];
1097	    e->info.load_seconds = li.seconds;
1098	  }
