  2	// Formats: docs/spec/QUANT_FORMATS.md. The runs layout is its "Wide loads" section: a slice of n blocks is stored as
  3	// one run per field, field f of block k at run_offset(f, n) + k * field_size(f), the largest fields first.
  4	#ifndef SHARED_QUANT_H
  5	#define SHARED_QUANT_H
  6	
  7	#include "types.h"
  8	
  9	// ggml type ids (ggml/include/ggml.h at the pinned commit).
 10	#define QT_F32 0
 11	#define QT_F16 1
 12	#define QT_Q4_0 2
 13	#define QT_Q5_0 6
 14	#define QT_Q8_0 8
 15	#define QT_Q8_1 9
 16	#define QT_Q3_K 11
 17	#define QT_Q4_K 12
 18	#define QT_Q5_K 13
 19	#define QT_Q6_K 14
 20	#define QT_Q8_K 15
 21	#define QT_IQ2_XXS 16
 22	#define QT_IQ2_XS 17
 23	#define QT_IQ3_XXS 18
 24	#define QT_IQ4_NL 20
 25	#define QT_IQ3_S 21
 26	#define QT_IQ2_S 22
 27	#define QT_IQ4_XS 23
 28	#define QT_IQ1_M 29
 29	#define QT_BF16 30
 30	#define QT_Q2_0 42
 31	
 32	// Values per block.
 33	SHARED_FN u32 quant_block_values(u32 t) {
 34	  switch (t) {
 35	    case QT_Q4_0: case QT_Q5_0: case QT_Q8_0: case QT_Q8_1: case QT_IQ4_NL: return 32;
 36	    case QT_Q2_0: return 64;
 37	    case QT_Q3_K: case QT_Q4_K: case QT_Q5_K: case QT_Q6_K: case QT_Q8_K:
 38	    case QT_IQ1_M: case QT_IQ2_XXS: case QT_IQ2_XS:
 39	    case QT_IQ3_XXS: case QT_IQ3_S: case QT_IQ2_S: case QT_IQ4_XS: return 256;
 40	    default: return 1;
 41	  }
 42	}
 43	
 44	// Bytes per block; 0 for a type the engine does not read.
 45	SHARED_FN u32 quant_block_bytes(u32 t) {
 46	  switch (t) {
 47	    case QT_F32: return 4;
 48	    case QT_F16: case QT_BF16: return 2;
 49	    case QT_Q4_0: return 18;
 50	    case QT_Q5_0: return 22;
 51	    case QT_Q8_0: return 34;
 52	    case QT_Q8_1: return 36;
 53	    case QT_Q3_K: return 110;
 54	    case QT_Q4_K: return 144;
 55	    case QT_Q5_K: return 176;
 56	    case QT_Q6_K: return 210;
 57	    case QT_Q8_K: return 292;
 58	    case QT_IQ1_M: return 56;
 59	    case QT_IQ2_XXS: return 66;
 60	    case QT_IQ2_XS: return 74;
 61	    case QT_IQ3_XXS: return 98;
 62	    case QT_IQ4_NL: return 18;
 63	    case QT_IQ3_S: return 110;
 64	    case QT_IQ2_S: return 82;
 65	    case QT_IQ4_XS: return 136;
 66	    case QT_Q2_0: return 18;
 67	    default: return 0;
 68	  }
 69	}
 70	
 71	// Fields of a block in run order: (offset in the file's block, size). Quants first, f16 scales last.
 72	SHARED_FN u32 quant_nfields(u32 t) {
 73	  switch (t) {
 74	    case QT_IQ2_S: case QT_IQ3_S: return 5;
 75	    case QT_IQ4_XS: case QT_Q3_K: case QT_Q5_K: case QT_Q6_K: return 4;
 76	    case QT_IQ1_M: case QT_IQ2_XS: case QT_IQ3_XXS: case QT_Q4_K: case QT_Q5_0: return 3;
 77	    case QT_IQ2_XXS: case QT_IQ4_NL: case QT_Q2_0: case QT_Q4_0: case QT_Q8_0: return 2;
 78	    default: return 1;
 79	  }
 80	}
 81	
 82	// Encoded as (offset << 8) | size.
 83	SHARED_FN u32 quant_field_(u32 t, u32 f) {
 84	  switch (t) {
 85	    case QT_IQ2_S: {  // qs (grid index low bits), signs, qh, scales, d
 86	      const u32 v[5] = {(2u << 8) | 32, (34u << 8) | 32, (66u << 8) | 8, (74u << 8) | 8, (0u << 8) | 2};
 87	      return v[f];
 88	    }
 89	    case QT_IQ1_M: {  // qs (grid index low bits), qh, scales (with d in their top nibbles)
 90	      const u32 v[3] = {(0u << 8) | 32, (32u << 8) | 16, (48u << 8) | 8};
 91	      return v[f];
 92	    }
 93	    case QT_IQ2_XXS: {  // grid indices and scale-and-sign words, d
 94	      const u32 v[2] = {(2u << 8) | 64, (0u << 8) | 2};
 95	      return v[f];
 96	    }
 97	    case QT_IQ2_XS: {  // 9-bit grid indices with 7 sign bits, scales, d
 98	      const u32 v[3] = {(2u << 8) | 64, (66u << 8) | 8, (0u << 8) | 2};
 99	      return v[f];
100	    }
101	    case QT_IQ3_XXS: {  // grid indices, scale-and-sign words, d
102	      const u32 v[3] = {(2u << 8) | 64, (66u << 8) | 32, (0u << 8) | 2};
103	      return v[f];
104	    }
105	    case QT_IQ3_S: {  // qs, signs, qh, scales, d
106	      const u32 v[5] = {(2u << 8) | 64, (74u << 8) | 32, (66u << 8) | 8, (106u << 8) | 4, (0u << 8) | 2};
107	      return v[f];
108	    }
109	    case QT_IQ4_XS: {  // qs, scales_l, scales_h, d
110	      const u32 v[4] = {(8u << 8) | 128, (4u << 8) | 4, (2u << 8) | 2, (0u << 8) | 2};
111	      return v[f];
112	    }
113	    case QT_IQ4_NL: case QT_Q2_0: {  // qs, d
114	      const u32 v[2] = {(2u << 8) | 16, (0u << 8) | 2};
115	      return v[f];
116	    }
117	    case QT_Q4_0: {  // qs, d
118	      const u32 v[2] = {(2u << 8) | 16, (0u << 8) | 2};
119	      return v[f];
120	    }
121	    case QT_Q5_0: {  // qs, qh, d
122	      const u32 v[3] = {(6u << 8) | 16, (2u << 8) | 4, (0u << 8) | 2};
123	      return v[f];
124	    }
125	    case QT_Q8_0: {  // qs, d
126	      const u32 v[2] = {(2u << 8) | 32, (0u << 8) | 2};
127	      return v[f];
128	    }
129	    case QT_Q3_K: {  // qs, hmask, scales, d
130	      const u32 v[4] = {(32u << 8) | 64, (0u << 8) | 32, (96u << 8) | 12, (108u << 8) | 2};
131	      return v[f];
132	    }
133	    case QT_Q4_K: {  // qs, scales, d and dmin
134	      const u32 v[3] = {(16u << 8) | 128, (4u << 8) | 12, (0u << 8) | 4};
135	      return v[f];
136	    }
137	    case QT_Q5_K: {  // qs, qh, scales, d and dmin
138	      const u32 v[4] = {(48u << 8) | 128, (16u << 8) | 32, (4u << 8) | 12, (0u << 8) | 4};
139	      return v[f];
140	    }
141	    case QT_Q6_K: {  // ql, qh, scales, d
142	      const u32 v[4] = {(0u << 8) | 128, (128u << 8) | 64, (192u << 8) | 16, (208u << 8) | 2};
143	      return v[f];
144	    }
145	    default: return quant_block_bytes(t);
146	  }
147	}
