149	SHARED_FN u32 quant_field_offset(u32 t, u32 f) { return quant_field_(t, f) >> 8; }
150	SHARED_FN u32 quant_field_size(u32 t, u32 f) { return quant_field_(t, f) & 0xff; }
151	
152	// Where field f's run starts in a slice of n blocks.
153	SHARED_FN u64 quant_run_offset(u32 t, u32 f, u64 n) {
154	  u64 off = 0;
155	  for (u32 g = 0; g < f; g++) off += quant_field_size(t, g);
156	  return off * n;
157	}
