 1	// The step plan: what the cards compute in one step. The host writes it into host memory, and the kernels read it
 2	// where it lies (docs/DESIGN.md, sections 2 and 3). Fixed size: a recorded step list reads the same address every
 3	// step.
 4	#ifndef SHARED_STEP_H
 5	#define SHARED_STEP_H
 6	
 7	#include "types.h"
 8	
 9	#define STEP_MAX_ROWS 8
10	
11	// One row: one token of one sequence.
12	typedef struct {
13	  u32 slot;   // the sequence's slot: which state and KV it reads and writes
14	  u32 pos;    // the token's position in its sequence
15	  u32 token;  // the token id
16	  u32 flags;  // STEP_ROW_*
17	} StepRow;
18	
19	#define STEP_ROW_LOGITS 1u  // the row's logits are wanted
20	
21	typedef struct {
22	  u32 nrows;
23	  u32 step;    // counts steps, for the timing records
24	  u32 window;  // 1: the rows are windows of consecutive positions, one run of rows per sequence, and the recurrent
25	               // state is not committed; a commit (CommitPlan) then writes the accepted rows' state
26	  u32 pad;
27	  StepRow rows[STEP_MAX_ROWS];
28	} StepPlan;
29	
30	// After a window: in each of nruns runs, the n rows from window row row0 (the accepted ones) commit their recurrent
31	// state, from position pos0 of slot.
32	typedef struct {
33	  u32 n;
34	  u32 pos0;
35	  u32 slot;
36	  u32 row0;
37	} CommitRun;
38	
39	typedef struct {
40	  u32 nruns;
41	  u32 pad[3];
42	  CommitRun runs[STEP_MAX_ROWS];
43	} CommitPlan;
44	
45	SHARED_ASSERT(sizeof(CommitRun) == 16, "CommitRun layout");
46	SHARED_ASSERT(sizeof(CommitPlan) == 16 + 16 * STEP_MAX_ROWS, "CommitPlan layout");
47	
48	// A prompt chunk: n consecutive tokens of one sequence from position pos0, all computed in one pass (the prompt
49	// path). The recorded chunk lists read it where it lies, so one list serves any n up to the size it was recorded for.
50	typedef struct {
51	  u32 n;
52	  u32 pos0;
53	  u32 slot;
54	  u32 step;
55	} PromptPlan;
56	
57	SHARED_ASSERT(sizeof(PromptPlan) == 16, "PromptPlan layout");
58	
59	// A slot's rotation in a decode step (docs/spec/MODEL_VISION.md, section 4.2). With images in the prompt a position is
60	// three numbers (time, height, width) and no longer the cell: a decode row at cell c turns by c - delta on all three.
61	// The indexer's block that starts at cell blk turns by (t, h, w), the positions of that cell, which may lie in an
62	// image; a later block turns by its first cell less delta. Without images delta is 0 and (t, h, w) = (blk, blk, blk).
63	typedef struct {
64	  u32 delta;
65	  u32 blk;
66	  u32 t, h, w;
67	  u32 pad[3];
68	} SlotRope;
69	
70	// A prompt chunk's positions are (t, h, w, 0) per cell in host memory, from the first cell of the chunk's first block
71	// (pos0 rounded down to a multiple of 4) to its last row.
72	SHARED_ASSERT(sizeof(StepRow) == 16, "StepRow layout");
73	SHARED_ASSERT(sizeof(SlotRope) == 32, "SlotRope layout");
74	SHARED_ASSERT(sizeof(StepPlan) == 16 + 16 * STEP_MAX_ROWS, "StepPlan layout");
75	
76	#endif

